// Kalendar sa interneta: aplikacija pri pokretanju povlači races.json sa GitHub-a i koristi ga
// ako je noviji od ugrađenog (SEED_GENERATED). Bez mreže ostaje poslednji sačuvani ili ugrađeni.
const REMOTE_URL = "https://raw.githubusercontent.com/srdjan89np/moje-trke/main/races.json";
const REMOTE_KEY = "trke-kalendar-v1";
const SEED_GENERATED = "2026-11-09T11:20:41Z";

function cleanRemote(data) {
  if (!data || typeof data.generated !== "string" || !Array.isArray(data.races)) return null;
  const races = data.races.filter(
    (r) =>
      r && typeof r.id === "string" && typeof r.name === "string" && typeof r.city === "string" &&
      /^\d{4}-\d{2}-\d{2}$/.test(r.date) && (r.type === "trail" || r.type === "city") &&
      Array.isArray(r.distances) && r.distances.every((d) => d && d.km > 0 && d.gain >= 0) &&
      (r.reg === undefined || /^https?:\/\/\S+$/.test(r.reg))
  );
  return races.length >= 50 ? { generated: data.generated, races } : null;
}

