/* --------------------------- race card --------------------------- */

const STATUS_KEY = { interested: "chipInterested", registered: "chipRegistered", done: "chipDone" };

// Ridge + tone zajednički za karticu i detalje.
function raceLook(race) {
  const hasDist = race.distances.length > 0;
  const hardest = hasDist ? race.distances.reduce((a, b) => (b.km > a.km ? b : a), race.distances[0]) : null;
  return {
    hasDist,
    steepness: hardest ? Math.min(1, hardest.gain / (hardest.km * 55)) : 0.35,
    tone: race.type === "trail" ? "var(--ochre)" : "var(--teal)",
  };
}

function RaceMeta({ race }) {
  const t = useT();
  const lang = useLang();
  const cc = countryOf(race);
  const away = daysUntil(race.date);
  return (
    <p className="card-meta">
      <span className={`tag tag-${race.type}`}>{race.type === "trail" ? t.tagTrail : t.tagCity}</span>
      <span className="flag" role="img" aria-label={countryName(cc, lang)} title={countryName(cc, lang)}>{flagOf(cc)}</span>
      <span className="city">{race.city}</span>
      <span className="nowrap when">
        <svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true">
          <circle cx="12" cy="12" r="8.5" fill="none" stroke="currentColor" strokeWidth="2" />
          <path d="M12 7.5V12l3 2" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
        </svg>
        {away >= 0 ? <span className="away">{t.inDays(away)}</span> : <span className="away past">{t.pastRace}</span>}
      </span>
      {race.edited && <span className="tag tag-edt">{t.tagEdited}</span>}
      {race.unconfirmed && (
        <span className="tag tag-unc" title={t.uncTitle}>
          {t.tagUnc}
        </span>
      )}
    </p>
  );
}

// Kartica u listi: samo najvažnije; dodir otvara detalje trke.
function RaceCard({ race, entry, onOpen }) {
  const lang = useLang();
  const t = useT();
  const { hasDist, steepness, tone } = raceLook(race);
  const d = fmtDate(race.date, lang);
  const status = entry?.status || null;
  const done = status === "done";

  return (
    <article className={`card card-tap${done ? " card-done" : ""}`} data-testid={`race-${race.id}`}>
      <button type="button" className="card-hit" onClick={() => onOpen(race.id)} aria-label={t.openDetails(race.name)} data-testid={`open-${race.id}`} />
      <div className="card-ridge" style={{ color: tone }}>
        <Ridge seed={race.id} steepness={steepness} tone={tone} filled={done} />
      </div>

      <div className="card-date" aria-hidden="true">
        <span className="cd-day">{d.day}</span>
        <span className="cd-mon">{d.mon}</span>
        <span className="cd-yr">{d.year}</span>
      </div>

      <div className="card-body">
        <h3 className="card-name">{race.name}</h3>
        <RaceMeta race={race} />

        <ul className="dists">
          {hasDist ? (
            race.distances.map((x, i) => (
              <li key={i} className="dist">
                <b>{x.km}</b> km {x.gain > 0 && <span className="gain">↑{x.gain} m</span>}
              </li>
            ))
          ) : (
            <li className="dist dist-tbd">{t.distTbd}</li>
          )}
        </ul>

        {(status || entry?.result) && (
          <div className="card-foot">
            {status && <span className={`pill pill-${status}`} data-testid={`pill-${race.id}`}>✓ {t[STATUS_KEY[status]]}</span>}
            {done && entry?.result && (
              <span className="pill-res" data-testid={`result-${race.id}`}>
                <b>{fmtSecs(entry.result.secs)}</b> · {entry.result.km} km
              </span>
            )}
          </div>
        )}
      </div>
      <svg className="card-chev" viewBox="0 0 24 24" width="22" height="22" aria-hidden="true">
        <path d="M9 5l7 7-7 7" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    </article>
  );
}

// Detalji trke: preko celog ekrana; ovde su sve akcije.
function RaceDetail({ race, entry, tracking, onSet, onClear, onEdit, onLog, onClose, onShare }) {
  const t = useT();
  const lang = useLang();
  const ref = useRef(null);
  const { hasDist, steepness, tone } = raceLook(race);
  const status = entry?.status || null;
  const done = status === "done";
  const res = entry?.result;
  const away = daysUntil(race.date);
  const cc = countryOf(race);

  useEffect(() => {
    ref.current?.focus();
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = prev; };
  }, []);
  useEffect(() => {
    // Esc / Android „nazad" zatvara samo prozor koji je na vrhu.
    const esc = (e) => {
      if (e.key !== "Escape") return;
      const all = document.querySelectorAll('[aria-modal="true"]');
      if (all[all.length - 1] === ref.current) onClose();
    };
    window.addEventListener("keydown", esc);
    return () => window.removeEventListener("keydown", esc);
  }, [onClose]);

  let longDate = "";
  try {
    longDate = parseDate(race.date).toLocaleDateString(lang === "sr" ? "sr-Latn-RS" : "en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" });
  } catch {
    const d = fmtDate(race.date, lang);
    longDate = `${d.day} ${d.mon} ${d.year}`;
  }

  // Lični rekord: najbolje vreme među svim upisanim rezultatima na istoj dužini.
  let pr = false;
  if (res) {
    const same = Object.values(tracking).filter((e) => e.result && Math.abs(e.result.km - res.km) < 0.01);
    pr = same.length > 1 && same.every((e) => e.result.secs >= res.secs);
  }
  const mapUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${race.city === "—" ? "" : race.city}, ${countryName(cc, "en")}`)}`;

  return (
    <div className="overlay overlay-form overlay-detail">
      <div className="modal modal-form modal-detail" role="dialog" aria-modal="true" aria-labelledby="det-h" tabIndex={-1} ref={ref} data-testid="race-detail">
        <header className="mf-head det-head">
          <button type="button" className="icon-btn" onClick={onClose} aria-label={t.back} data-testid="detail-back">
            <svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true">
              <path d="M15 5l-7 7 7 7" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </button>
          <h2 id="det-h" className="det-title">{race.name}</h2>
        </header>

        <div className="mf-body det-body">
          <section className="det-hero">
            <div className="det-ridge" style={{ color: tone }}>
              <Ridge seed={race.id} steepness={steepness} tone={tone} filled />
            </div>
            <p className="det-date">{longDate}</p>
            <RaceMeta race={race} />
            {race.unconfirmed && <p className="hint det-note">{t.uncTitle}</p>}
          </section>

          <section className="det-sec">
            <h3 className="det-h">{t.legsH}</h3>
            {hasDist ? (
              <ul className="det-legs">
                {race.distances.map((x, i) => (
                  <li key={i}>
                    <b>{x.km} km</b>
                    <span>{x.gain > 0 ? `↑ ${x.gain} m` : "—"}</span>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="hint">{t.distTbd}</p>
            )}
          </section>

          <section className="det-sec">
            <h3 className="det-h">{t.yourStatus}</h3>
            <div className="seg" role="group" aria-label={t.status}>
              {["interested", "registered", "done"].map((st) => (
                <button key={st} type="button" className="seg-btn" aria-pressed={status === st}
                  onClick={() => onSet(race.id, st)}
                  data-testid={`${st === "interested" ? "int" : st === "registered" ? "reg" : "done"}-${race.id}`}>
                  {t[STATUS_KEY[st]]}
                </button>
              ))}
            </div>
            <p className="hint det-hint">{t.statusHint}</p>
          </section>

          {(done || res) && (
            <section className="det-sec">
              <h3 className="det-h">{t.resultH}</h3>
              {res ? (
                <div className="det-res" data-testid={`detail-result-${race.id}`}>
                  <div className="det-res-top">
                    <span className="res-time">{fmtSecs(res.secs)}</span>
                    {pr && <span className="pr" data-testid="pr">🏅 {t.pr(res.km)}</span>}
                  </div>
                  <dl className="det-res-grid">
                    <div><dt>{t.leg}</dt><dd>{res.km} km</dd></div>
                    <div><dt>{t.paceL}</dt><dd>{pace(res.secs, res.km)}</dd></div>
                    {res.place > 0 && <div><dt>{t.placing}</dt><dd>{t.placeShort(res.place)}</dd></div>}
                  </dl>
                  {res.note && <p className="det-res-note">{res.note}</p>}
                </div>
              ) : (
                <p className="hint">{t.resultEmpty}</p>
              )}
              {hasDist && (
                <button type="button" className={`btn ${res ? "btn-outline" : "btn-primary"} det-wide`} onClick={() => onLog(race.id)} data-testid={`log-open-${race.id}`}>
                  {res ? t.editResult : t.logResult}
                </button>
              )}
            </section>
          )}

          <section className="det-sec det-actions">
            {race.reg && away >= 0 && (
              <a className="btn btn-primary reg-link det-wide" href={race.reg} target="_blank" rel="noopener noreferrer" data-testid={`prijava-${race.id}`}>
                {t.signUp}
              </a>
            )}
            <button type="button" className="btn btn-outline det-wide" onClick={() => onShare(raceShareCard(race, entry, t, lang))} data-testid={`share-race-${race.id}`}>
              <ShareIco /> {t.shareRaceBtn}
            </button>
            <a className="btn btn-outline det-wide" href={mapUrl} target="_blank" rel="noopener noreferrer">{t.onMap}</a>
            <button type="button" className="btn btn-outline det-wide" onClick={() => onEdit(race)} data-testid={`edit-${race.id}`}>
              {t.fix}
            </button>
            {(status || res) && (
              <button type="button" className="btn btn-ghost danger det-wide" onClick={() => onClear(race.id)} data-testid={`clear-${race.id}`}>
                {t.remove}
              </button>
            )}
          </section>
        </div>
      </div>
    </div>
  );
}

// Upis rezultata na posebnom ekranu: deonica i vreme obavezni, plasman i beleška po želji.
function ResultForm({ race, entry, onSave, onClose }) {
  const t = useT();
  const saved = entry?.result;
  const multi = race.distances.length > 1;
  const savedIdx = saved ? race.distances.findIndex((d) => Math.abs(d.km - saved.km) < 0.01) : -1;
  const [distIdx, setDistIdx] = useState(savedIdx >= 0 ? String(savedIdx) : multi ? "" : "0");
  const [dur, setDur] = useState(saved ? secsToDigits(saved.secs) : "");
  const [place, setPlace] = useState(saved?.place ? String(saved.place) : "");
  const [note, setNote] = useState(saved?.note || "");
  const [err, setErr] = useState({ field: "", msg: "" });
  const first = useRef(null);

  useEffect(() => { first.current?.focus(); }, []);
  useEffect(() => {
    const esc = (e) => {
      if (e.key !== "Escape") return;
      const all = document.querySelectorAll('[aria-modal="true"]');
      const me = all[all.length - 1];
      if (me && me.getAttribute("data-testid") === "result-form") onClose();
    };
    window.addEventListener("keydown", esc);
    return () => window.removeEventListener("keydown", esc);
  }, [onClose]);

  const leg = distIdx === "" ? null : race.distances[Number(distIdx)];
  const { h, m, s: sec } = parseDur(dur);
  const secs = h * 3600 + m * 60 + sec;
  const livePace = leg && dur && m <= 59 && sec <= 59 && secs > 0 ? pace(secs, leg.km) : "—";
  const Msg = ({ k }) => (err.field === k ? <p className="err" role="alert" data-testid={`err-${k}`}>{err.msg}</p> : null);
  const clear = (k) => err.field === k && setErr({ field: "", msg: "" });

  const submit = () => {
    if (!leg) return setErr({ field: "leg", msg: t.errLeg });
    if (m > 59 || sec > 59) return setErr({ field: "time", msg: t.errMinSec });
    if (secs <= 0) return setErr({ field: "time", msg: t.errNoTime });
    if (secs >= 60 * 3600) return setErr({ field: "time", msg: t.errTooLong });
    const pl = place.trim();
    if (pl && !/^\d{1,6}$/.test(pl)) return setErr({ field: "place", msg: t.errPlace });
    if (pl && Number(pl) < 1) return setErr({ field: "place", msg: t.errPlace });
    const result = { km: leg.km, gain: leg.gain, secs };
    if (pl) result.place = Number(pl);
    if (note.trim()) result.note = note.trim().slice(0, 500);
    onSave(race.id, result);
  };

  const footer = (
    <>
      <button type="button" className="btn btn-outline" onClick={onClose}>{t.cancel}</button>
      <button type="button" className="btn btn-primary" onClick={submit} data-testid={`save-${race.id}`}>{t.saveResult}</button>
    </>
  );

  return (
    <FormSheet titleId="res-h" title={saved ? t.editResult : t.logResult} sub={race.name} onClose={onClose} onSubmit={submit} footer={footer} testid="result-form">
      <p className="req-note">{t.reqNote}</p>
      <div className="grid2">
        <div className="fld fld-wide">
          <label className="lab" htmlFor="r-leg">{t.leg} <Req /></label>
          {multi ? (
            <select ref={first} id="r-leg" className={`input${err.field === "leg" ? " input-bad" : ""}${distIdx === "" ? " select-empty" : ""}`} value={distIdx} onChange={(e) => { setDistIdx(e.target.value); clear("leg"); }} data-testid={`leg-${race.id}`}>
              <option value="" disabled>{t.pickLeg}</option>
              {race.distances.map((x, i) => (
                <option key={i} value={i}>{x.km} km{x.gain > 0 ? ` · ↑${x.gain} m` : ""}</option>
              ))}
            </select>
          ) : (
            <span className="log-leg">{race.distances[0].km} km{race.distances[0].gain > 0 ? ` · ↑${race.distances[0].gain} m` : ""}</span>
          )}
          <Msg k="leg" />
        </div>
        <div className="fld">
          <label className="lab" htmlFor="r-time">{t.time} <Req /></label>
          <input
            ref={multi ? null : first}
            id="r-time"
            className={`input time-in${err.field === "time" ? " input-bad" : ""}`}
            inputMode="numeric"
            enterKeyHint="next"
            autoComplete="off"
            placeholder={t.timePh}
            value={fmtDur(dur)}
            onChange={(e) => { setDur(durDigits(e.target.value)); clear("time"); }}
            aria-describedby="r-time-hint"
            data-testid={`time-${race.id}`}
          />
          <span id="r-time-hint" className="hint">{t.timeHint}</span>
          <Msg k="time" />
        </div>
        <div className="fld">
          <span className="lab">{t.paceL}</span>
          <span className="log-leg pace-out" data-testid="live-pace">{livePace}</span>
          <span className="hint">{t.paceAuto}</span>
        </div>
        <div className="fld">
          <label className="lab" htmlFor="r-place">{t.placing}</label>
          <input id="r-place" className={`input${err.field === "place" ? " input-bad" : ""}`} inputMode="numeric" enterKeyHint="next" value={place} onChange={(e) => { setPlace(e.target.value.replace(/\D/g, "").slice(0, 6)); clear("place"); }} placeholder={t.placingPh} data-testid="r-place" />
          <Msg k="place" />
        </div>
        <div className="fld fld-wide">
          <label className="lab" htmlFor="r-note">{t.note}</label>
          <textarea id="r-note" className="input r-note" rows={3} maxLength={500} value={note} onChange={(e) => setNote(e.target.value)} placeholder={t.notePh} data-testid="r-note" />
        </div>
      </div>
    </FormSheet>
  );
}

/* ------------------------- add race dialog ----------------------- */

function EditRace({ race, hasEdit, onSave, onReset, onDelete, onClose }) {
  const t = useT();
  const [date, setDate] = useState(race.date);
  const [city, setCity] = useState(race.city === "—" ? "" : race.city);
  const [rows, setRows] = useState(race.distances.length ? race.distances.map((d) => ({ km: String(d.km), gain: String(d.gain) })) : [{ km: "", gain: "" }]);
  const [reg, setReg] = useState(race.reg || "");
  const [err, setErr] = useState({ field: "", msg: "" });
  const [confirm, setConfirm] = useState(false);
  const mine = String(race.id).startsWith("mine-");

  useEffect(() => {
    const esc = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", esc);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", esc);
      document.body.style.overflow = prev;
    };
  }, [onClose]);

  const setRow = (i, key, v) => { setRows(rows.map((r, j) => (i === j ? { ...r, [key]: v } : r))); if (err.field === "dist") setErr({ field: "", msg: "" }); };
  const addRow = () => setRows([...rows, { km: "", gain: "" }]);
  const dropRow = (i) => setRows(rows.filter((_, j) => j !== i));
  const Msg = ({ k }) => (err.field === k ? <p className="err" role="alert" data-testid="edit-err">{err.msg}</p> : null);

  const submit = () => {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return setErr({ field: "date", msg: t.errDate });
    const parsed = [];
    for (const r of rows) {
      if (r.km.trim() === "" && r.gain.trim() === "") continue;
      const km = numIn(r.km);
      if (!(km > 0 && km <= 500)) return setErr({ field: "dist", msg: t.errKmAll });
      const gain = r.gain.trim() === "" ? 0 : parseInt(r.gain, 10);
      if (!(gain >= 0 && gain <= 20000)) return setErr({ field: "dist", msg: t.errGainAll });
      parsed.push({ km, gain });
    }
    if (!parsed.length) return setErr({ field: "dist", msg: t.errOneLeg });
    const link = reg.trim();
    if (link && !URL_RE.test(link)) return setErr({ field: "reg", msg: t.errUrl });
    parsed.sort((a, b) => b.km - a.km);
    onSave(race.id, { date, city: city.trim(), distances: parsed, reg: link });
  };

  const footer = (
    <>
      {hasEdit && (
        <button type="button" className="btn btn-ghost mr-auto" onClick={() => onReset(race.id)} data-testid="edit-reset">
          {t.restore}
        </button>
      )}
      <button type="button" className="btn btn-outline" onClick={onClose}>{t.cancel}</button>
      <button type="button" className="btn btn-primary" onClick={submit} data-testid="edit-submit">{t.saveEdit}</button>
    </>
  );

  return (
    <FormSheet titleId="edit-h" title={t.editTitle} sub={race.name} onClose={onClose} onSubmit={submit} footer={footer} testid="edit-dialog">
      <p className="req-note">{t.reqNote}</p>
      <div className="grid2">
        <div className="fld">
          <label className="lab" htmlFor="e-date">{t.date} <Req /></label>
          <DateField id="e-date" value={date} onChange={(e) => { setDate(e.target.value); setErr({ field: "", msg: "" }); }} bad={err.field === "date"} testid="edit-date" />
          <Msg k="date" />
        </div>
        <div className="fld">
          <label className="lab" htmlFor="e-city">{t.place}</label>
          <input id="e-city" className="input" enterKeyHint="next" value={city} onChange={(e) => setCity(e.target.value)} placeholder={t.phCity} />
        </div>
        <div className="fld fld-wide">
          <label className="lab" htmlFor="e-reg">{t.regLink}</label>
          <input id="e-reg" className={`input${err.field === "reg" ? " input-bad" : ""}`} type="url" inputMode="url" enterKeyHint="next" autoComplete="off" value={reg} onChange={(e) => setReg(e.target.value)} placeholder="https://…" data-testid="edit-reg" />
          <Msg k="reg" />
        </div>
      </div>

      <LegRows rows={rows} setRow={setRow} addRow={addRow} dropRow={dropRow} prefix="edit" />
      <Msg k="dist" />

      {mine && (
        <div className="del-zone">
          {confirm ? (
            <>
              <span className="del-ask">{t.deleteAsk(race.name)}</span>
              <button type="button" className="btn btn-danger" onClick={() => onDelete(race.id)} data-testid="del-yes">{t.wipeYes}</button>
              <button type="button" className="btn btn-outline" onClick={() => setConfirm(false)}>{t.wipeNo}</button>
            </>
          ) : (
            <button type="button" className="btn btn-ghost danger" onClick={() => setConfirm(true)} data-testid="del-race">
              {t.deleteRace}
            </button>
          )}
        </div>
      )}
    </FormSheet>
  );
}

function Bell({ items, permission, onAsk }) {
  const t = useT();
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    if (!open) return;
    const away = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const esc = (e) => e.key === "Escape" && setOpen(false);
    document.addEventListener("mousedown", away);
    window.addEventListener("keydown", esc);
    return () => {
      document.removeEventListener("mousedown", away);
      window.removeEventListener("keydown", esc);
    };
  }, [open]);

  return (
    <div className={`bell-wrap${open ? " open" : ""}`} ref={ref}>
      {open && <div className="bell-backdrop" aria-hidden="true" onClick={() => setOpen(false)} />}
      <button
        type="button"
        className="bell"
        onClick={() => setOpen((v) => !v)}
        aria-label={items.length ? `${t.reminders} (${items.length})` : t.reminders}
        aria-expanded={open}
        data-testid="bell"
      >
        <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
          <path d="M18 8a6 6 0 1 0-12 0c0 6-2 7-2 7h16s-2-1-2-7M13.7 20a2 2 0 0 1-3.4 0"
                fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
        {items.length > 0 && <span className="bell-dot" data-testid="bell-count">{items.length}</span>}
      </button>

      {open && (
        <div className="bell-panel" role="dialog" aria-label={t.reminders} data-testid="bell-panel">
          <h3 className="bell-h">{t.next7}</h3>
          {items.length === 0 ? (
            <p className="bell-empty">
              {t.bellEmpty}
            </p>
          ) : (
            <ul className="bell-list">
              {items.map(({ race, days, status }) => (
                <li key={race.id} className="bell-item">
                  <span className={`bell-days${days <= 1 ? " soon" : ""}`}>
                    {days === 0 ? t.today : days === 1 ? t.tomorrow : t.inNDays(days)}
                  </span>
                  <span className="bell-name">{race.name}</span>
                  <span className="bell-city">
                    {race.city} · {status === "registered" ? t.stEntered : t.stInterested}
                  </span>
                </li>
              ))}
            </ul>
          )}
          {permission === "default" && (
            <button type="button" className="btn btn-primary bell-ask" onClick={onAsk} data-testid="bell-ask">
              {t.bellAsk}
            </button>
          )}
          <p className="bell-note">
            {permission === "granted"
              ? nativeLN() ? t.bellNative : t.bellGranted
              : t.bellDefault}
          </p>
        </div>
      )}
    </div>
  );
}

function ConfirmWipe({ count, onConfirm, onClose }) {
  const t = useT();
  const first = useRef(null);

  useEffect(() => { first.current?.focus(); }, []);
  useEffect(() => {
    const esc = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", esc);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", esc);
      document.body.style.overflow = prev;
    };
  }, [onClose]);

  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal modal-sm" role="alertdialog" aria-modal="true" aria-labelledby="wipe-h" data-testid="wipe-dialog">
        <h2 id="wipe-h" className="modal-h">{t.wipeTitle}</h2>
        <p className="wipe-p">
          {count > 0
            ? t.wipeCount(count)
            : t.nothingToWipe}
        </p>
        <p className="wipe-p wipe-warn">{t.wipeWarn}</p>
        <div className="modal-actions">
          <button ref={first} type="button" className="btn" onClick={onClose} data-testid="wipe-no">{t.giveUp}</button>
          <button type="button" className="btn btn-danger" onClick={onConfirm} data-testid="wipe-yes">{t.wipeAll}</button>
        </div>
      </div>
    </div>
  );
}

function ImportDialog({ info, onMerge, onReplace, onClose }) {
  const t = useT();
  const lang = useLang();
  const first = useRef(null);

  useEffect(() => { first.current?.focus(); }, []);
  useEffect(() => {
    const esc = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", esc);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", esc);
      document.body.style.overflow = prev;
    };
  }, [onClose]);

  const d = info.data;
  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal modal-sm" role="dialog" aria-modal="true" aria-labelledby="imp-h" data-testid="import-dialog">
        <h2 id="imp-h" className="modal-h">{t.importTitle}</h2>
        <p className="wipe-p">{t.importInfo(Object.keys(d.tracking).length, d.custom.length, info.exported ? fmtDay(info.exported, lang) : "")}</p>
        <p className="wipe-p imp-how">{t.importHow}</p>
        <div className="modal-actions">
          <button ref={first} type="button" className="btn" onClick={onClose} data-testid="import-no">{t.giveUp}</button>
          <button type="button" className="btn btn-danger" onClick={onReplace} data-testid="import-replace">{t.importReplace}</button>
          <button type="button" className="btn btn-primary" onClick={onMerge} data-testid="import-merge">{t.importMerge}</button>
        </div>
      </div>
    </div>
  );
}

function AddRace({ onAdd, onClose }) {
  const t = useT();
  const lang = useLang();
  // Podloga i zemlja namerno nisu unapred izabrane.
  const [f, setF] = useState({ name: "", city: "", date: "", type: "", country: "", reg: "" });
  const [rows, setRows] = useState([{ km: "", gain: "" }]);
  const [err, setErr] = useState({ field: "", row: -1, msg: "" });
  const first = useRef(null);

  useEffect(() => { first.current?.focus(); }, []);
  useEffect(() => {
    const esc = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", esc);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", esc);
      document.body.style.overflow = prev;
    };
  }, [onClose]);

  const clearErr = () => setErr({ field: "", row: -1, msg: "" });
  const set = (k) => (e) => {
    setF({ ...f, [k]: e.target.value });
    if (err.field === k) clearErr();
  };
  const setRow = (i, key, v) => {
    setRows(rows.map((r, j) => (i === j ? { ...r, [key]: v } : r)));
    if (err.field === "dist") clearErr();
  };
  const addRow = () => setRows([...rows, { km: "", gain: "" }]);
  const dropRow = (i) => {
    setRows(rows.filter((_, j) => j !== i));
    if (err.field === "dist") clearErr();
  };
  const bad = (k) => (err.field === k ? " input-bad" : "");
  const badRow = (i) => (err.field === "dist" && err.row === i ? " input-bad" : "");
  const Msg = ({ k }) =>
    err.field === k ? <p className="err" role="alert" data-testid={`err-${k}`}>{err.msg}</p> : null;

  const submit = () => {
    if (!f.name.trim()) return setErr({ field: "name", row: -1, msg: t.errName });
    if (!/^\d{4}-\d{2}-\d{2}$/.test(f.date)) return setErr({ field: "date", row: -1, msg: t.errDate });
    if (!f.type) return setErr({ field: "type", row: -1, msg: t.errType });
    if (!f.country) return setErr({ field: "country", row: -1, msg: t.errCountry });
    const parsed = [];
    for (let i = 0; i < rows.length; i++) {
      const r = rows[i];
      if (r.km.trim() === "" && r.gain.trim() === "") continue;
      const km = numIn(r.km);
      if (!(km > 0 && km <= 500))
        return setErr({ field: "dist", row: i, msg: t.errKm(i + 1) });
      const gain = r.gain.trim() === "" ? 0 : parseInt(r.gain, 10);
      if (!(gain >= 0 && gain <= 20000))
        return setErr({ field: "dist", row: i, msg: t.errGain(i + 1) });
      parsed.push({ km, gain });
    }
    if (!parsed.length) return setErr({ field: "dist", row: 0, msg: t.errOneLeg });
    const reg = f.reg.trim();
    if (reg && !URL_RE.test(reg)) return setErr({ field: "reg", row: -1, msg: t.errUrl });
    parsed.sort((a, b) => b.km - a.km);
    onAdd({
      id: `mine-${Date.now()}`,
      name: f.name.trim(),
      city: f.city.trim() || "—",
      country: f.country,
      type: f.type,
      date: f.date,
      distances: parsed,
      ...(reg ? { reg } : {}),
    });
  };

  const footer = (
    <>
      <button type="button" className="btn btn-outline" onClick={onClose}>{t.cancel}</button>
      <button type="button" className="btn btn-primary" onClick={submit} data-testid="add-submit">{t.submitAdd}</button>
    </>
  );

  return (
    <FormSheet titleId="add-h" title={t.addTitle} onClose={onClose} onSubmit={submit} footer={footer} testid="add-dialog">
      <p className="req-note">{t.reqNote}</p>
      <div className="grid2">
        <div className="fld fld-wide">
          <label className="lab" htmlFor="a-name">{t.name} <Req /></label>
          <input ref={first} id="a-name" className={`input${bad("name")}`} aria-invalid={err.field === "name"} aria-required="true" enterKeyHint="next" value={f.name} onChange={set("name")} placeholder={t.phName} data-testid="add-name" />
          <Msg k="name" />
        </div>
        <div className="fld">
          <label className="lab" htmlFor="a-city">{t.place}</label>
          <input id="a-city" className="input" enterKeyHint="next" value={f.city} onChange={set("city")} placeholder={t.phCity} />
        </div>
        <div className="fld">
          <label className="lab" htmlFor="a-date">{t.date} <Req /></label>
          <DateField id="a-date" value={f.date} onChange={set("date")} bad={err.field === "date"} testid="add-date" />
          <Msg k="date" />
        </div>
        <div className="fld">
          <label className="lab" htmlFor="a-type">{t.surface} <Req /></label>
          <select id="a-type" className={`input${bad("type")}${f.type ? "" : " select-empty"}`} aria-invalid={err.field === "type"} aria-required="true" value={f.type} onChange={set("type")} data-testid="add-type">
            <option value="" disabled>{t.pick}</option>
            <option value="trail">{t.surfaceTrail}</option>
            <option value="city">{t.surfaceCity}</option>
          </select>
          <Msg k="type" />
        </div>
        <div className="fld">
          <label className="lab" htmlFor="a-country">{t.country} <Req /></label>
          <select id="a-country" className={`input${bad("country")}${f.country ? "" : " select-empty"}`} aria-invalid={err.field === "country"} aria-required="true" value={f.country} onChange={set("country")} data-testid="add-country">
            <option value="" disabled>{t.pick}</option>
            <optgroup label={t.region}>
              {["RS", "BA", "ME", "HR", "MK", "SI"].map((k) => (
                <option key={k} value={k}>{countryName(k, lang)}</option>
              ))}
            </optgroup>
            <optgroup label={t.restOfEurope}>
              {Object.keys(COUNTRIES)
                .filter((k) => !["RS", "BA", "ME", "HR", "MK", "SI"].includes(k))
                .map((k) => [k, countryName(k, lang)])
                .sort((a, b) => a[1].localeCompare(b[1], lang))
                .map(([k, v]) => (
                  <option key={k} value={k}>{v}</option>
                ))}
            </optgroup>
          </select>
          <Msg k="country" />
        </div>
        <div className="fld fld-wide">
          <label className="lab" htmlFor="a-reg">{t.regLink}</label>
          <input id="a-reg" className={`input${bad("reg")}`} aria-invalid={err.field === "reg"} type="url" inputMode="url" enterKeyHint="next" autoComplete="off" value={f.reg} onChange={set("reg")} placeholder="https://…" aria-describedby="a-reg-hint" data-testid="add-reg" />
          <span id="a-reg-hint" className="hint">{t.regHint}</span>
          <Msg k="reg" />
        </div>
      </div>

      <LegRows rows={rows} setRow={setRow} addRow={addRow} dropRow={dropRow} badRow={badRow} prefix="add" />
      <Msg k="dist" />
    </FormSheet>
  );
}

/* --------------------------- tabovi ------------------------------- */

const HOME_CC_KEY = "trke-home-cc";
const kmKey = (km) => String(Math.round(km * 10) / 10);

// Kratak red trke (početna, statistika): dodir otvara detalje.
function RaceRow({ race, entry, onOpen, sub }) {
  const t = useT();
  const lang = useLang();
  const d = fmtDate(race.date, lang);
  const cc = countryOf(race);
  const status = entry?.status;
  return (
    <button type="button" className="row-race" onClick={() => onOpen(race.id)} data-testid={`row-${race.id}`}>
      <span className="rr-date"><b>{d.day}</b><span>{d.mon}</span></span>
      <span className="rr-tx">
        <b>{race.name}</b>
        <span>{sub || <><span className={`tag tag-${race.type}`}>{race.type === "trail" ? t.tagTrail : t.tagCity}</span> {flagOf(cc)} {race.city}</>}</span>
      </span>
      {status ? <span className={`pill pill-${status}`}>{status === "done" ? "✓" : t[STATUS_KEY[status]]}</span> : <span className="rr-chev" aria-hidden="true">›</span>}
    </button>
  );
}

function MiniCard({ race, onOpen }) {
  const t = useT();
  const lang = useLang();
  const { steepness, tone } = raceLook(race);
  const away = daysUntil(race.date);
  const d = fmtDate(race.date, lang);
  const km = race.distances.map((x) => String(x.km).replace(".", lang === "sr" ? "," : ".")).join(" / ");
  return (
    <button type="button" className="mini" onClick={() => onOpen(race.id)} data-testid={`mini-${race.id}`}>
      <span className="mini-d">{d.day} {d.mon} · {t.inDays(away)}</span>
      <span className="mini-n">{race.name}</span>
      <span className="mini-m"><span className={`tag tag-${race.type}`}>{race.type === "trail" ? t.tagTrail : t.tagCity}</span> {race.city}{km ? ` · ${km} km` : ""}</span>
      <span className="mini-ridge" style={{ color: tone }}><Ridge seed={race.id} steepness={steepness} tone={tone} /></span>
    </button>
  );
}

function SecHead({ children, link, onLink, testid }) {
  return (
    <div className="sec-h">
      <h2>{children}</h2>
      {link && <button type="button" className="sec-link" onClick={onLink} data-testid={testid}>{link}</button>}
    </div>
  );
}

function HomeTab({ races, tracking, stats, homeCC, setHomeCC, countryChips, onOpen, onFind, onAdd, onStats, countryCount, onNew, newSeen, onFeedback, onShare }) {
  const t = useT();
  const lang = useLang();
  const next = stats.upcoming;
  const anyMarks = Object.keys(tracking).length > 0;

  const soon = useMemo(() => races.filter((r) => countryOf(r) === homeCC && daysUntil(r.date) >= 0).slice(0, 10), [races, homeCC]);
  const weekend = useMemo(() => {
    const now = new Date();
    const dow = now.getDay(); // 0 = nedelja
    const toSun = dow === 0 ? 0 : 7 - dow;
    return races.filter((r) => {
      const a = daysUntil(r.date);
      if (a < 0 || a > toSun) return false;
      const wd = parseDate(r.date).getDay();
      return (wd === 0 || wd === 5 || wd === 6) && countryOf(r) === homeCC;
    }).slice(0, 6);
  }, [races, homeCC]);
  const mine = useMemo(
    () => races.filter((r) => ["interested", "registered"].includes(tracking[r.id]?.status) && daysUntil(r.date) >= 0 && r.id !== next?.id),
    [races, tracking, next]
  );
  // Rekord na najdužoj deonici sledeće trke, ako postoji.
  let pb = null;
  if (next && next.distances.length) {
    const km = kmKey(Math.max(...next.distances.map((x) => x.km)));
    for (const e of Object.values(tracking)) if (e.result && kmKey(e.result.km) === km && (!pb || e.result.secs < pb)) pb = e.result.secs;
  }

  return (
    <div className="tab-pane" data-testid="tab-home-pane">
      {next ? (
        <section className="hero-card" data-testid="next-race">
          <p className="hc-lbl">{t.nextLbl}</p>
          <h2 className="hc-name">{next.name}</h2>
          <RaceMeta race={next} />
          <div className="hc-count">
            <div><b>{daysUntil(next.date)}</b><span>{t.daysToStart(daysUntil(next.date))}</span></div>
            {next.distances.length > 0 && <div><b>{Number(Math.max(...next.distances.map((x) => x.km)).toFixed(1)).toLocaleString(lang === "sr" ? "sr-Latn-RS" : "en-GB")}</b><span>km</span></div>}
            {pb && <div><b>{fmtSecs(pb)}</b><span>{t.yourPb}</span></div>}
          </div>
          <div className="hc-btns">
            <button type="button" className="btn btn-outline" onClick={() => onOpen(next.id)}>{t.details}</button>
            {next.reg && <a className="btn btn-primary reg-link" href={next.reg} target="_blank" rel="noopener noreferrer">{t.signUp}</a>}
            <button type="button" className="btn btn-outline share-icon-btn" onClick={() => onShare(raceShareCard(next, tracking[next.id], t, lang))} aria-label={t.share} title={t.share} data-testid="share-next">
              <ShareIco />
            </button>
          </div>
        </section>
      ) : (
        <section className="hero-card hero-card-plain" data-testid="welcome">
          <p className="hc-lbl">{anyMarks ? t.noNextLbl : t.welcomeLbl}</p>
          <h2 className="hc-name">{anyMarks ? t.noNextH : t.welcomeH}</h2>
          <p className="hc-p">{anyMarks ? t.noNextP : t.welcomeP(races.length, countryCount)}</p>
          <div className="hc-btns">
            <button type="button" className="btn btn-primary" onClick={onFind} data-testid="find-race">{t.findRace}</button>
            <button type="button" className="btn btn-outline" onClick={onAdd}>{t.addOwn}</button>
          </div>
        </section>
      )}

      <section>
        <div className="sec-h">
          <h2 className="sec-cc">
            {t.soonIn}{" "}
            <span className="cc-pick">
              {flagOf(homeCC)} {countryShort(homeCC, lang)} ▾
              <select aria-label={t.homeCountry} value={homeCC} onChange={(e) => setHomeCC(e.target.value)} data-testid="home-cc">
                {countryChips.map((cc) => <option key={cc} value={cc}>{countryShort(cc, lang)}</option>)}
              </select>
            </span>
          </h2>
          <button type="button" className="sec-link" onClick={() => onFind(homeCC)} data-testid="home-all">{t.allRaces}</button>
        </div>
        {soon.length ? (
          <div className="carousel">{soon.map((r) => <MiniCard key={r.id} race={r} onOpen={onOpen} />)}</div>
        ) : (
          <p className="hint">{t.noSoon}</p>
        )}
      </section>

      {weekend.length > 0 && (
        <section>
          <SecHead>{t.weekend}</SecHead>
          <div className="rows-list">{weekend.map((r) => <RaceRow key={r.id} race={r} entry={tracking[r.id]} onOpen={onOpen} />)}</div>
        </section>
      )}

      {anyMarks && (
        <section>
          <SecHead link={t.statsLink} onLink={onStats}>{t.seasonH(new Date().getFullYear())}</SecHead>
          <div className="stats">
            <Stat label={t.statDone} value={stats.km} unit="km" sub={t.statRaces(stats.done)} />
            <Stat label={t.statReg} value={stats.reg} />
            <Stat label={t.statGain} value={stats.gain} unit="m" />
          </div>
        </section>
      )}

      {mine.length > 0 && (
        <section>
          <SecHead>{t.yourRaces(mine.length)}</SecHead>
          <div className="rows-list">
            {mine.slice(0, 8).map((r) => (
              <RaceRow key={r.id} race={r} entry={tracking[r.id]} onOpen={onOpen}
                sub={<>{flagOf(countryOf(r))} {r.city} · {t.inDays(daysUntil(r.date))}</>} />
            ))}
          </div>
        </section>
      )}
      <button type="button" className="new-row" onClick={onNew} data-testid="open-new">
        <span className="new-row-ico" aria-hidden="true">
          <svg viewBox="0 0 24 24" width="22" height="22"><path d="M12 3l1.8 4.9L19 9.7l-4.2 2.9L16 18l-4-3-4 3 1.2-5.4L5 9.7l5.2-1.8z" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinejoin="round" /></svg>
        </span>
        <span className="new-row-tx"><b>{t.newH}</b><span>{t.newSub}</span></span>
        {!newSeen && <span className="pill new-badge">{t.newBadge}</span>}
        <span className="rr-chev" aria-hidden="true">›</span>
      </button>
    </div>
  );
}

function StatsTab({ races, tracking, onOpen, onFind, onShare, children }) {
  const t = useT();
  const lang = useLang();
  const byId = useMemo(() => new Map(races.map((r) => [r.id, r])), [races]);
  const all = useMemo(() => {
    const out = [];
    for (const [id, e] of Object.entries(tracking)) {
      const r = byId.get(id);
      if (r && e.result) out.push({ race: r, res: e.result });
    }
    return out.sort((a, b) => b.race.date.localeCompare(a.race.date));
  }, [tracking, byId]);
  const years = [...new Set(all.map((x) => x.race.date.slice(0, 4)))].sort().reverse();
  const thisYear = String(new Date().getFullYear());
  const [period, setPeriod] = useState(years.includes(thisYear) || !years.length ? thisYear : years[0]);
  const list = period === "all" ? all : all.filter((x) => x.race.date.startsWith(period));

  const km = list.reduce((a, x) => a + x.res.km, 0);
  const gain = list.reduce((a, x) => a + (x.res.gain || 0), 0);
  const secs = list.reduce((a, x) => a + x.res.secs, 0);
  const hrs = `${Math.floor(secs / 3600)}:${String(Math.floor((secs % 3600) / 60)).padStart(2, "0")}`;

  // Grafikon: po mesecima za jednu godinu, po godinama za „Ukupno".
  const bars = useMemo(() => {
    if (period === "all") {
      const ys = [...years].reverse();
      return ys.map((y) => ({ k: y, label: y, v: all.filter((x) => x.race.date.startsWith(y)).reduce((a, x) => a + x.res.km, 0) }));
    }
    return MONTHS[lang].map((m, i) => ({ k: m, label: m, v: list.filter((x) => Number(x.race.date.slice(5, 7)) === i + 1).reduce((a, x) => a + x.res.km, 0) }));
  }, [period, list, all, years, lang]);
  const maxBar = Math.max(1, ...bars.map((b) => b.v));

  const prs = useMemo(() => {
    const best = new Map();
    for (const x of all) {
      const k = kmKey(x.res.km);
      if (!best.has(k) || x.res.secs < best.get(k).res.secs) best.set(k, x);
    }
    return [...best.values()].sort((a, b) => a.res.km - b.res.km);
  }, [all]);

  return (
    <div className="tab-pane" data-testid="tab-stats-pane">
      {all.length === 0 ? (
        <section className="hero-card hero-card-plain">
          <h2 className="hc-name">{t.tabStats}</h2>
          <p className="hc-p">{t.statsEmpty}</p>
          <div className="hc-btns"><button type="button" className="btn btn-primary" onClick={() => onFind()}>{t.findRace}</button></div>
        </section>
      ) : (
        <>
          <div className="seg seg-wide" role="group">
            {[...years.slice(0, 2), "all"].map((y) => (
              <button key={y} type="button" className="seg-btn" aria-pressed={period === y} onClick={() => setPeriod(y)} data-testid={`period-${y}`}>
                {y === "all" ? t.total : y}
              </button>
            ))}
          </div>
          <section>
            <SecHead link={<><ShareIco /> {t.share}</>} testid="share-stats" onLink={() => onShare({
              kind: "stats", file: "moje-trke-statistika.png",
              title: period === "all" ? t.shareAll : t.shareSeason(period),
              km: Math.round(km), races: list.length, gain, hrs, prsTitle: t.prsH,
              prs: prs.slice().sort((a, b) => b.res.km - a.res.km).slice(0, 3).map((x) => ({ time: fmtSecs(x.res.secs), km: `${Number(x.res.km.toFixed(1)).toLocaleString(lang === "sr" ? "sr-Latn-RS" : "en-GB")} km`, pace: pace(x.res.secs, x.res.km) })),
              text: t.shareTextStats(period === "all" ? t.shareAll : t.shareSeason(period), Math.round(km), list.length),
            })}>{period === "all" ? t.total : t.season(period)}</SecHead>
            <div className="stats" data-testid="season-stats">
              <Stat label={t.statKm} value={Math.round(km)} unit="km" sub={t.statRaces(list.length)} />
              <Stat label={t.statGain} value={gain} unit="m" />
              <Stat label={t.onCourse} value={hrs} unit="h" />
            </div>
          </section>
          <section>
            <SecHead>{period === "all" ? t.kmByYear : t.kmByMonth}</SecHead>
            <div className="chart" role="img" aria-label={bars.map((b) => `${b.label} ${Math.round(b.v)} km`).join(", ")}>
              {bars.map((b) => (
                <div key={b.k} className="bar">
                  {b.v > 0 && <em>{Math.round(b.v)}</em>}
                  <i style={{ height: `${(b.v / maxBar) * 100}%` }} />
                  <span>{b.label}</span>
                </div>
              ))}
            </div>
          </section>
          <section>
            <SecHead>{t.prsH}</SecHead>
            <div className="pr-box" data-testid="prs">
              {prs.map((x) => (
                <button key={kmKey(x.res.km)} type="button" className="pr-row" onClick={() => onOpen(x.race.id)}>
                  <span><b>{fmtSecs(x.res.secs)}</b><span>{x.res.km} km · {x.race.name}</span></span>
                  <span className="pr-pace">{pace(x.res.secs, x.res.km)}</span>
                </button>
              ))}
            </div>
          </section>
          <section>
            <SecHead>{t.finishedH(list.length)}</SecHead>
            <div className="rows-list">
              {list.map((x) => (
                <RaceRow key={x.race.id} race={x.race} entry={tracking[x.race.id]} onOpen={onOpen}
                  sub={<>{x.res.km} km · {fmtSecs(x.res.secs)}{x.res.place ? ` · ${t.placeShort(x.res.place)}` : ""}</>} />
              ))}
            </div>
          </section>
        </>
      )}
      <section>
        <SecHead>{t.dataH}</SecHead>
        {children}
      </section>
    </div>
  );
}

